-- Rifts World Book 33: Northern Gun One - the other weapons, ammunition, explosives, mines, fuel cells and batteries printed 101-103 and 213-218 that the catalog did not hold.
-- 37 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~283-northern-gun-1-weapons-other.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ng-standard-rail-gun-rounds', 'NG Standard Rail Gun Ammunition', 'rifts', 'gear', NULL, 2, '2-3 credits per standard round on average, plus the cost of the belt or ammo drum; orders over 10,000 rounds often get a 10% discount', 'By weapon', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s rail gun rounds, sold to fit the various rail gun calibers found in North America.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-monster-tracker-rail-gun-rounds', 'NG Monster Tracker Rail Gun Rounds', 'rifts', 'gear', NULL, 4, '4 credits a round', 'Rail gun damage -10%, rounded down', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A rail gun round carrying a liquid radioactive isotope that glows brightly in the infrared and drips a trail, so a regenerating monster that flees can be tracked down and re-engaged before it heals. The isotope is inert within 48 hours. To work, 10% of the standard ammunition is replaced with tracker rounds; they give +10% to the Tracking skill.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-armor-piercing-rail-gun-rounds', 'NG Armor Piercing Rail Gun Rounds', 'rifts', 'gear', NULL, 10, '10 credits per round', 'By weapon, not increased; Critical Strike on a Natural 19 or 20', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Rail gun rounds with a chemical coating, as on the armor piercing mini-missile, for easier penetration.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-shredder-rail-gun-rounds', 'NG Shredder Rail Gun Rounds', 'rifts', 'gear', NULL, 8, '8 credits per round', 'By weapon, +2 M.D. for each 20 rounds in the burst (+4 for a 40 round burst, +6 for a 60 round burst, and so on)', 1, 'The weapon''s range reduced by 20%', NULL, NULL, NULL, NULL, NULL, 'Specialty rounds released in 109 P.A. that balloon out like a flower petal on impact into a larger, serrated bullet. Their weight and design cut effective range by 20%.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-fragmentation-hand-grenade', 'NG Fragmentation Hand Grenade', 'rifts', 'weapon', NULL, 160, '160 credits', '2D4 M.D. to a 20 foot (6.1 m) area', 1, 'Thrown, about 120 feet (36 m)', NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s own fragmentation grenade, cheaper but slightly less powerful than the Coalition equivalent. NG also sells CS-equivalent grenades at the usual price.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-high-explosive-hand-grenade', 'NG High Explosive Hand Grenade', 'rifts', 'weapon', NULL, 120, '120 credits', '3D4 M.D. to a 6 foot (1.8 m) area', 1, 'Thrown, about 120 feet (36 m)', NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s own high explosive grenade, cheaper but slightly less powerful than the Coalition equivalent.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-plasma-hand-grenade', 'NG Plasma Hand Grenade', 'rifts', 'weapon', NULL, 275, '275 credits', '4D6 M.D. to a 12 foot (3.6 m) area', 1, 'Thrown, about 120 feet (36 m)', NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s own plasma grenade, cheaper but slightly less powerful than the Coalition equivalent.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-commercial-plastique', 'Commercial Plastique', 'rifts', 'weapon', NULL, 5, '5 credits an ounce', '1D4 S.D.C. per ounce (28 grams) or 1D6x10 S.D.C. per pound (0.45 kg)', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A wax or clay-like S.D.C. explosive shaped like putty into a patty, block, rope or blob. It will not go off if dropped, shaken, shot, blasted or set on fire; an electric charge, usually a blasting cap, detonates it, as can lightning or Electrokinesis. The blast stays concentrated where it was placed, with little shrapnel: for safe-cracking, sabotage, blowing locks and cutting girders.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-c4-military-plastique', 'C4 (Military HE) Plastique', 'rifts', 'weapon', NULL, 8, '8 credits an ounce', '1D6 S.D.C. per ounce or 2D4x10+20 S.D.C. per pound (0.45 kg)', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Military high explosive S.D.C. plastique, shaped like putty and detonated by a blasting cap; stable when dropped, shot or burned.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-sdc-dynamite', 'S.D.C. Dynamite', 'rifts', 'weapon', NULL, 10, '10 credits each', '5D6 S.D.C. per stick', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A stick of S.D.C. dynamite.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-md-dynamite', 'M.D. Dynamite', 'rifts', 'weapon', NULL, 130, '130 credits per stick. Fair availability', '2D4 M.D. per stick to a 10 foot (3 m) blast radius (printed as M.D.C.)', 1, 'Usually placed; not made for throwing, maximum effective throw 30-40 feet (9-12 m)', NULL, NULL, NULL, NULL, NULL, 'A Mega-Damage stick of dynamite, usually placed and detonated rather than thrown.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-2-md-plastique', 'NG 2 M.D. Plastique', 'rifts', 'weapon', NULL, 20, '20 credits an ounce or 320 credits per pound. Fair availability', '1 M.D. per ounce or 1D6 M.D. per pound (0.45 kg)', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s lightest Mega-Damage plastique, shaped like putty and detonated by a blasting cap.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-4-md-plastique', 'NG 4 M.D. Plastique', 'rifts', 'weapon', NULL, 40, '40 credits an ounce or 640 credits per pound. Poor to fair availability', '1D4 M.D. per ounce or 1D4x10 M.D. per pound (0.45 kg)', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s medium Mega-Damage plastique, shaped like putty and detonated by a blasting cap.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-6-md-plastique', 'NG 6 M.D. Plastique', 'rifts', 'weapon', NULL, 60, '60 credits an ounce or 960 credits per pound. Poor to fair availability', '1D6 M.D. per ounce or 2D4x10+20 M.D. per pound (printed 0.5 kg)', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s heaviest Mega-Damage plastique, shaped like putty and detonated by a blasting cap.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-blasting-cap', 'Blasting Cap', 'rifts', 'gear', NULL, 5, 'S.D.C. blasting cap 5 credits; M.D.C. blasting cap 40 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The electric detonator that sets off plastique, in S.D.C. and M.D.C. versions.', 'Rifts World Book 33: Northern Gun One p.213', NULL),
  ('ng-grenade-knife', 'Grenade Knife', 'rifts', 'weapon', 1, 450, 'S.D.C. Grenade Knife 450 credits each; Vibro-Blade version 9,500 credits each; add 500-1,200 credits for a silver-plated blade', 'Blade: 1D6 S.D.C. (S.D.C. blade) or 1D6 M.D. (Vibro-Blade) on impact. One melee action later the grenade handle explodes: 4D6 M.D. to the target it is embedded in and 1D6 M.D. to those within a 4 foot (1.2 m) blast radius on the same side of the target', 1, 'Thrown, about 30 feet (9 m)', 'One use; the blade is destroyed in the explosion', NULL, NULL, NULL, NULL, 'A knife with a fragmentation grenade for a handle, armed after the target is stabbed so the blade holds the blast against the victim; popular with Juicers, Crazies, Headhunters and gladiators. An S.D.C. blade bounces 2D4 feet off M.D. armor and most M.D. creatures and may hurt anyone in the blast radius. Thrown needs W.P. Targeting and is still -1 to strike; unskilled users can throw it within 15 feet (4.6 m) at -3.', 'Rifts World Book 33: Northern Gun One p.214', NULL),
  ('ng-gl10-grenade-launcher', 'NG-GL10 Grenade Launcher', 'rifts', 'weapon', 25, 50000, 'Includes 24 grenades. Grenades: plasma 500 credits each, high explosive/armor piercing 350, fragmentation 200, tear gas 250, stun 200, smoke 50', 'Fragmentation 3D6 M.D. to a 12 foot (3.7 m) radius; high explosive/armor piercing 4D6 M.D. to a 3 foot (0.9 m) radius; plasma 6D6 M.D. to a five foot (1.5 m) radius. Smoke covers a 40 foot (12.2 m) radius; tear gas a 25 foot (7.6 m) radius (-10 to strike, parry and dodge, -3 on initiative and one less melee attack while in it and for 1D6+1 melee rounds after, unless protected); stun/flash -10 to strike, parry and dodge, -1 on initiative and one less melee attack for 1D4 melee rounds', 1, '1,000 feet (305 m)', 'A six grenade clip, a 24 round drum, or a backpack ammo-pack of up to 60 rounds', 'Single shot only, each blast counting as one melee attack', NULL, NULL, NULL, 'A versatile grenade launcher rivalling Wellington Industries'' products, mounted on power armor and robots and carried by police and mercenaries. The lighter Block II weighs 19 lbs (8.6 kg). Clips add 1.5 lbs (0.7 kg), drums 6 lbs (2.7 kg) and a loaded ammo-pack about 15 lbs (6.8 kg). A P.S. under 20 is -2 to strike.', 'Rifts World Book 33: Northern Gun One p.214', NULL),
  ('ng-armor-piercing-mini-missile', 'NG Armor Piercing Mini-Missile', 'rifts', 'weapon', NULL, 2400, '2,400 credits each (the NG-ML6 entry prices its additional armor piercing missiles at 2,000)', '1D4x10 M.D.', 1, 'By launcher', NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s armor piercing mini-missile, standard issue for the NG-ML6 and NG-ML7.', 'Rifts World Book 33: Northern Gun One p.215', NULL),
  ('ng-fragmentation-mini-missile', 'NG Fragmentation Mini-Missile', 'rifts', 'weapon', NULL, 1200, '1,200 credits each', 'Not printed in this book''s price summary', 1, 'By launcher', NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s fragmentation mini-missile. The book prints its price only.', 'Rifts World Book 33: Northern Gun One p.215', NULL),
  ('ng-high-explosive-mini-missile', 'NG High-Explosive Mini-Missile', 'rifts', 'weapon', NULL, 1200, '1,200 credits each', 'Not printed in this book''s price summary', 1, 'By launcher', NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s high-explosive mini-missile. The book prints its price only.', 'Rifts World Book 33: Northern Gun One p.215', NULL),
  ('ng-plasma-napalm-mini-missile', 'NG Plasma/Napalm Mini-Missile', 'rifts', 'weapon', NULL, 2400, '2,400 credits each (the NG-ML6 entry prices its additional plasma missiles at 3,000)', 'Plasma 1D6x10 M.D.', 1, 'By launcher', NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s plasma/napalm mini-missile, standard issue for the NG-ML6 and NG-ML7.', 'Rifts World Book 33: Northern Gun One p.215', NULL),
  ('ng-smoke-tear-gas-mini-missile', 'NG Smoke/Tear Gas Mini-Missile', 'rifts', 'weapon', NULL, 800, '800 credits each', 'None; smoke or tear gas', 0, 'By launcher', NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s smoke or tear gas mini-missile. The book prints its price only.', 'Rifts World Book 33: Northern Gun One p.215', NULL),
  ('ng-ml6-mini-missile-cannon', 'NG-ML6 Mini-Missile Cannon', 'rifts', 'weapon', 16, 72000, 'Weapon alone; additional mini-missiles 2,000 credits for armor piercing and 3,000 for plasma', 'By mini-missile; standard issue is armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.)', 1, 'One mile (1.6 km)', '6 mini-missiles in a disposable box magazine; reloading takes two melee attacks', 'One at a time, each mini-missile counting as one melee attack', NULL, NULL, NULL, 'A large semi-automatic smoothbore cannon that launches mini-missiles on compressed air before their rockets ignite, so it has none of the usual dangerous backblast; used by power armor troopers, cyborgs and two-man fire teams. Weight is plus each mini-missile. Passive nightvision (3,000 feet/914 m), thermal imaging (1,200 feet/366 m) and laser targeting (3,000 feet/914 m, +1 to strike). A P.S. of 18 or less is -2 to strike unless crewed by two.', 'Rifts World Book 33: Northern Gun One p.215', NULL),
  ('ng-ml7-mini-missile-launcher', 'NG-ML7 Mini-Missile Launcher', 'rifts', 'weapon', 30, 34000, '34,000 credits', 'By missile; armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.) are standard', 1, 'About one mile (1.6 km)', '4 mini-missiles; reloading all four takes 8 melee attacks', 'One at a time or in volleys of two or four', NULL, NULL, NULL, 'A shoulder-fired quad-tube launcher built to compete with Wellington Industries'' WI-23, able to fire salvoes or keep different missile types ready; heavy and bulky. Weight is fully loaded. NG also sells a WI-23 knock-off as the NG-ML46.', 'Rifts World Book 33: Northern Gun One p.215', NULL),
  ('ng-anti-personnel-mine', 'NG Anti-Personnel Mine', 'rifts', 'weapon', NULL, 600, '600 credits for the standard mine, 1,200 with sensor. Poor availability even at NG outlets', '4D6 M.D. to a 40 foot (12 m) area', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A fragmentary or incendiary land mine triggered by a trip wire or 100 lbs (45 kg) or more of pressure. The sensor version detonates on a human-sized creature 6 feet (1.8 m) away, or a robot, cyborg, giant or light vehicle up to 12 feet (3.6 m) away. Spotting mines on foot uses Detect Ambush or Detect Concealment at -10%.', 'Rifts World Book 33: Northern Gun One p.216', NULL),
  ('ng-light-anti-vehicle-mine', 'NG Light Anti-Vehicle Mine', 'rifts', 'weapon', NULL, 1000, '1,000 credits for HE, 2,000 for plasma. Poor availability even at NG outlets', 'High explosive 5D6 M.D. to a 20 foot (6.1 m) area, or plasma 1D4x10 M.D. to a 30 foot (9.1 m) area', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Type One. Its sensor detects a vehicle under 5 tons at 3 feet (one meter), 5-10 tons at 10 feet (3 m) and over 10 tons at 20 feet (6 m); people on foot set it off only by stepping on it, and it can be detonated by radio. Creatures over 400 lbs (180 kg) count as light vehicles.', 'Rifts World Book 33: Northern Gun One p.216', NULL),
  ('ng-medium-anti-vehicle-mine', 'NG Medium Anti-Vehicle Mine', 'rifts', 'weapon', NULL, 3000, '3,000 credits for HE, 4,000 for plasma. Poor availability even at NG outlets', 'High explosive 1D6x10 M.D. or plasma 2D4x10 M.D.; areas as the light mine (20 feet HE, 30 feet plasma)', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Type Two: the light anti-vehicle mine with more damage; detection range unchanged, and radio detonation.', 'Rifts World Book 33: Northern Gun One p.216', NULL),
  ('ng-heavy-anti-vehicle-mine', 'NG Heavy Anti-Vehicle Mine', 'rifts', 'weapon', NULL, 6000, '6,000 credits for HE, 8,000 for plasma. Poor availability even at NG outlets', 'High explosive 2D6x10 M.D. or plasma 3D6x10 M.D., both to a 70 foot (21 m) blast area', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Type Three: the light anti-vehicle mine with still greater damage and blast area; same detection ranges and radio detonation.', 'Rifts World Book 33: Northern Gun One p.216', NULL),
  ('ng-nm3-firefly-plasma-mine', 'NG NM-3 Firefly Plasma Mine', 'rifts', 'weapon', 6, 1000, '1,000 credits. Poor availability even at NG outlets', 'Direct hit 5D6 M.D. to everyone in a 6 foot (1.8 m) radius; 1D6 M.D. to anyone within 40 feet (12.2 m)', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'An anti-personnel plasma mine that pops a grenade-like charge 3 feet (1 m) into the air before it bursts, showering the area with plasma. Triggered by 50 lbs (22.5 kg) of pressure or a trip wire.', 'Rifts World Book 33: Northern Gun One p.216', NULL),
  ('ng-nm4-claymore-mine', 'NG NM-4 Claymore', 'rifts', 'weapon', 3, 750, '750 credits; add 1,500 for a high-tech sensor. Poor availability even at NG outlets', '4D6 M.D. to everything within six feet (1.8 m) of the blast and 1D4 M.D. to everything else in the blast', 1, 'Directional cone 100 feet (30.5 m) long in a 120 degree arc', NULL, NULL, NULL, NULL, NULL, 'A modern Mega-Damage claymore after the US Army M18A1, hurling nearly two hundred M.D.C. ball bearings like those of the NG-101 rail gun. Normally command detonated by det cord; a sensor package detects motion and human-sized targets up to six feet (1.8 m) away.', 'Rifts World Book 33: Northern Gun One p.216', NULL),
  ('ng-nm9-plasmore-mine', 'NG NM-9 Plasmore Mine', 'rifts', 'weapon', 4, 1000, '1,000 credits; add 1,500 for a high-tech sensor. Poor availability even at NG outlets', '1D4x10 M.D. to those directly in the blast (within 12 feet/3.6 m) and 1D6 M.D. to everyone else in the blast', 1, 'Directional cone 100 feet (30.5 m) long in a 120 degree arc', NULL, NULL, NULL, NULL, NULL, 'A claymore-style directional mine that fires gobs of super-heated plasma instead of ball bearings. Usually command detonated by a handheld detonator; a sensor detects human-sized targets up to 12 feet (3.6 m) away.', 'Rifts World Book 33: Northern Gun One p.216-217', NULL),
  ('ng-nmbs11-bio-sensor-mine', 'NG NMBS-11 Bio-Sensor Mine', 'rifts', 'weapon', 3, 2800, '2,800 credits. Fair to poor availability in North America', '1D4x10 M.D. at point-blank range (within 6 feet/1.8 m) and 2D6 M.D. to everything within a 15 foot (4.6 m) blast radius', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'An anti-monster fragmentation mine developed for the CS whose bio-sensor reads thermal signature, heart rate and vital signs, scanning up to 12 signatures at once. It detonates on large inhuman creatures (Gargoyles, Brodkil, demons, dragons) and never while a human is in the blast radius; harmless to humans and many (not all) D-Bees.', 'Rifts World Book 33: Northern Gun One p.217', NULL),
  ('ng-nm12c-smart-scatter-mines', 'NG NM-12C "Smart" Scatter Mines', 'rifts', 'weapon', 1, 4800, '4,800 credits for a canister of 20 mines; transponder 1,200. Limited to the CS and its authorized allies; on the Black Market (rare) a canister is 12,000-24,000 credits and transponders 2,000-6,000 each', '3D6 M.D. per mine to everything within a 5 foot (1.5 m) blast radius', 1, NULL, '20 hockey-puck sized micro-fusion mines per canister, scattered over a 100 x 100 foot (30.5 x 30.5 m) area', NULL, NULL, NULL, NULL, 'A cluster mine canister delivered by aircraft, artillery or missile launcher that breaks apart in the air to lay an instant minefield. Each mine''s sensor detects a human-sized creature at 10 feet (3 m) or a cyborg, giant or robot at 30 feet (9.1 m), and ignores anyone carrying an NG transponder. Weight is per mine.', 'Rifts World Book 33: Northern Gun One p.217', NULL),
  ('ng-nmx18-stinger-anti-flyer-mine', 'NG NMX-18 Stinger Anti-Flyer Mine', 'rifts', 'weapon', 45, 140000, 'Launch cube 140,000 credits plus the Stingers at 2,500 credits each. Fair to poor availability in North America', '5D6 M.D. direct from the plasma warhead plus 1D4 M.D. to everything in a 30 foot (9.1 m) blast radius', 1, '3,600 feet (1,097 m); detection range 2 miles (3.2 km)', '12 Stinger drone warheads; reloading takes about 5 minutes', 'One at a time or in volleys of 2 or 4; three launches per melee round', NULL, NULL, 31, 'A computerized launch cube that fires hovering drone warheads at flyers it is programmed to engage (up to 3,200 target types, or any flyer). Radar 2 miles (3.2 km), Read Sensory Equipment 88%, recognition equal to the Wilk''s PC-2020 at 94%. Drones are +3 to strike, +1 to dodge with three attacks per melee round, but top out at 300 mph (480 km) and are -2 to strike against fast targets; victims who mistake them for birds are -3 on initiative and -1 to dodge. Prying at or damaging the cube makes it launch at the cause. Weight is the cube; Stingers weigh one pound (0.45 kg) each.', 'Rifts World Book 33: Northern Gun One p.218', NULL),
  ('ng-standard-solid-oxide-fuel-cell', 'NG Standard Solid Oxide Fuel Cell', 'rifts', 'gear', 42, 40000, '40,000 credits; NG buys back used, undamaged cells for 15% of list price. Conversion kits: jetpack or small power unit 25,000, motorcycle or hovercycle 30,000, personal vehicle, hovercar or ATV 45,000, power armor 75,000', 'If ruptured: 4D6 M.D. to everything in a 6 foot (1.8 m) radius', 1, NULL, '1,400 hours (about eight weeks of constant use)', NULL, NULL, NULL, 15, 'A ''Solid OX'' fuel cell for power armor, hovercycles, personal vehicles and jet packs, an alternative to a nuclear power supply; returned to an NG outlet to be recharged. It runs at about 1,000 degrees C: touching a hot one does 1D4 M.D. to M.D. creatures or 2D4x10 S.D.C. to humans. Charging another vehicle drains 50% of its life, and added energy weapons cut it 25%. At 5 M.D.C. or less it has a 50% chance of exploding every minute; at zero it explodes. M.D.C. is the protective casing.', 'Rifts World Book 33: Northern Gun One p.101-102', NULL),
  ('ng-heavy-duty-solid-oxide-fuel-cell', 'NG Heavy-Duty Solid Oxide Fuel Cell', 'rifts', 'gear', 221, 120000, '120,000 credits; NG buys back used, undamaged cells for 15% of list price. Conversion kits: combat robots and patrol boats 125,000; aircraft, military and large construction vehicles, large boats, barges and small ships 200,000', 'If ruptured: 1D6x10 M.D. to a 10 foot (3 m) radius', 1, NULL, '700 hours (about four weeks of constant use)', NULL, NULL, NULL, 30, 'A ''Solid OX'' fuel cell for tanks, combat robots, power armor with heavy energy weapons, and large vehicles and aircraft. It runs at about 1,000 degrees C: touching a hot one does 1D4 M.D. to M.D. creatures or 2D4x10 S.D.C. to humans. Charging another vehicle drains 50% of its life, and added energy weapons cut it 25%. At 5 M.D.C. or less it has a 50% chance of exploding every minute; at zero it explodes. M.D.C. is the protective casing.', 'Rifts World Book 33: Northern Gun One p.101-102', NULL),
  ('ng-electric-battery', 'NG Electric Battery', 'rifts', 'gear', 31, 25000, '25,000 credits per battery, plus 90,000 to install the electric battery system; recharge 200 credits per battery at most NG stores and weapon dealers', NULL, 0, NULL, '96 hours (4 days) of continuous use in robots and heavy vehicles; 144 hours (6 days) in man-sized power armor (9 feet/2.7 m and smaller), hovercycles, rocket bikes and light vehicles', NULL, NULL, NULL, 10, 'A rechargeable battery power option offered on most NG vehicle and robot designs. Small units take one battery, power armor and medium vehicles two, combat robots and larger vehicles four in series. A full charge takes 5 hours (3 at an NG outlet) from almost any generator, grid or nuclear-powered vehicle. Lasts five years in normal use, 1D4 years under combat conditions. Used as a generator it needs an Operator or Electrical Engineer, or it overloads and dies. M.D.C. is the protective casing.', 'Rifts World Book 33: Northern Gun One p.102-103', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 37 gear rows are in' AS assertion, count(*) AS got, 37 AS want
  FROM gear WHERE slug IN ('ng-standard-rail-gun-rounds', 'ng-monster-tracker-rail-gun-rounds', 'ng-armor-piercing-rail-gun-rounds', 'ng-shredder-rail-gun-rounds', 'ng-fragmentation-hand-grenade', 'ng-high-explosive-hand-grenade', 'ng-plasma-hand-grenade', 'ng-commercial-plastique', 'ng-c4-military-plastique', 'ng-sdc-dynamite', 'ng-md-dynamite', 'ng-2-md-plastique', 'ng-4-md-plastique', 'ng-6-md-plastique', 'ng-blasting-cap', 'ng-grenade-knife', 'ng-gl10-grenade-launcher', 'ng-armor-piercing-mini-missile', 'ng-fragmentation-mini-missile', 'ng-high-explosive-mini-missile', 'ng-plasma-napalm-mini-missile', 'ng-smoke-tear-gas-mini-missile', 'ng-ml6-mini-missile-cannon', 'ng-ml7-mini-missile-launcher', 'ng-anti-personnel-mine', 'ng-light-anti-vehicle-mine', 'ng-medium-anti-vehicle-mine', 'ng-heavy-anti-vehicle-mine', 'ng-nm3-firefly-plasma-mine', 'ng-nm4-claymore-mine', 'ng-nm9-plasmore-mine', 'ng-nmbs11-bio-sensor-mine', 'ng-nm12c-smart-scatter-mines', 'ng-nmx18-stinger-anti-flyer-mine', 'ng-standard-solid-oxide-fuel-cell', 'ng-heavy-duty-solid-oxide-fuel-cell', 'ng-electric-battery') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~283-northern-gun-1-weapons-other.sql');
